(() => {
  const lines: string[] = [];
  const collect = (parent: EntityProperty<T>, parentKey: string) => {
    for (const childProp of meta.props) {
      if (childProp.embedded?.[0] !== parent.name || !(childProp.object || childProp.persist !== false)) {
        continue;
      }

      const childDataKey =
        meta.embeddable || parent.object ? parentKey + this.wrap(childProp.embedded![1]) : this.wrap(childProp.name);
      lines.push(`${padding}  ret${childDataKey} = null;`);

      if (childProp.kind === ReferenceKind.EMBEDDED && !childProp.object && !parent.object) {
        collect(childProp, childDataKey);
      }
    }
  };
  collect(prop, dataKey);
  return lines.join('\n');
})() + `\n`;

